	if state.EndedAt != nil {
		fmt.Fprintf(w, "Ended:       %s (%s)\n",
			state.EndedAt.Local().Format("2006-01-02 15:04"), timeAgo(*state.EndedAt))
	}

	if state.LastInteractionTime != nil {
		fmt.Fprintf(w, "Last active: %s (%s)\n",
