	}

	if state.LastPrompt != "" {
		fmt.Fprintf(w, "\nLast prompt: %q\n", state.LastPrompt)
	}

	if len(state.FilesTouched) > 0 {
		fmt.Fprintln(w, "\nFiles touched:")
		for _, f := range state.FilesTouched {
			fmt.Fprintf(w, "  %s\n", f)
		}
	}

	return nil
}

