					fmt.Fprintf(w, "- %s: %d%% of %s tokens\n", contributor.Label, report.Context.Percent, formatTokenCount(report.Context.WindowSize))
				}
			default:
				fmt.Fprintf(w, "- %s\n", contributor.Label)
			}
		}
	}

	if len(report.Recommendations) > 0 {
		fmt.Fprintln(w)
		fmt.Fprintln(w, "Recommendations")
		for _, rec := range report.Recommendations {
			fmt.Fprintf(w, "- %s\n", rec.Message)
		}
	}

	if len(report.Limitations) > 0 {
		fmt.Fprintln(w)
		fmt.Fprintln(w, "Limitations")
		for _, limitation := range report.Limitations {
			fmt.Fprintf(w, "- %s\n", limitation)
		}
	}

	return nil
}

