+		signal = &tokensProfileSignal{
+			ID:    definition.id,
+			Label: definition.label,
+		}
+		signals[signalID] = signal
+	}
+	signal.Count++
+	if denominator > 0 {
+		signal.Percent = roundedPercent(signal.Count, denominator)
